<script setup>import {ref} from 'vue';import {Head,Link,router} from '@inertiajs/vue3';import Badge from '../Components/Badge.vue';import {statuses,date} from '../lib/labels';defineProps({incidents:Object,filters:Object});const q=ref(''),status=ref('');function filter(){router.get('/incidents',{q:q.value,status:status.value},{preserveState:true});}</script><template><Head title="Signalements"/><div class="page-heading heading-row"><div><span class="eyebrow">DU CONSTAT À LA REMISE EN SERVICE</span><h1>Les signalements</h1><p>Retrouvez les demandes de votre périmètre.</p></div><Link href="/signaler" class="btn btn-primary">+ Nouveau signalement</Link></div><form class="filters" @submit.prevent="filter"><input v-model="q" placeholder="Référence ou description" aria-label="Rechercher"><select v-model="status" aria-label="Statut"><option value="">Tous les statuts</option><option v-for="(label,s) in statuses" :value="s" :key="s">{{label}}</option></select><button class="btn btn-soft">Rechercher</button></form><section class="card table-card"><div class="table-wrap"><table><thead><tr><th>Référence / Point d’eau</th><th>Localité</th><th>Statut</th><th>Date</th><th></th></tr></thead><tbody><tr v-for="i in incidents.data" :key="i.id"><td><strong>{{i.water_point?.name||'Point non répertorié'}}</strong><small>{{i.reference}}</small></td><td>{{i.locality?.name}}</td><td><Badge :value="i.status"/></td><td>{{date(i.created_at)}}</td><td><Link :href="'/incidents/'+i.id" class="text-link">Ouvrir ↗</Link></td></tr><tr v-if="!incidents.data.length"><td colspan="5" class="empty">Aucun signalement ne correspond à votre recherche.</td></tr></tbody></table></div><div class="pagination"><template v-for="(l,k) in incidents.links" :key="k"><Link v-if="l.url" :href="l.url" :class="['btn','small',l.active?'btn-primary':'btn-soft']">{{k===0?'Précédent':k===incidents.links.length-1?'Suivant':l.label}}</Link></template></div></section></template>
